"use client";

import { cn } from "@/lib/utils";
// import HeaderLogo from "../../assets/solancn.svg";

import Image from "next/image";

const pathVariants = {
  hidden: {
    pathLength: 0,
    fillOpacity: 0,
  },
  visible: {
    pathLength: 1,
    fillOpacity: 1,
    transition: {
      duration: 2,
      ease: "easeInOut",
    },
  },
} as const;

const sizes: any = {
  sm: {
    svg: "h-6",
    betaTag: "bottom-[2px] left-[calc(100%+6px)] px-1.5 py-0.5 text-[9px]",
  },
  lg: {
    svg: "h-12",
    betaTag: "bottom-[4px] left-[calc(100%+10px)] px-2 py-0.5 text-base",
  },
  xl: {
    svg: "h-14",
    betaTag: "bottom-[7px] left-[calc(100%+15px)] px-2.5 py-1 text-base",
  },
  full: {
    svg: "h-full",
    betaTag: "bottom-[7px] left-[calc(100%+15px)] px-2.5 py-1 text-base",
  },
};

export function Logo({
  containerClassName,
  size,
  className,
  header,
  ...props
}: {
  containerClassName?: string;
  size?: "sm" | "lg" | "xl" | "full";
  className?: string;
  header?: boolean;
}) {
  return (
    <div className={cn("relative", containerClassName)}>
      <Image
        // src={header ? }
        src="/logo-round.png"
        alt="Logo"
        width={2400}
        height={1200}
        className={cn(
          sizes[size ?? "lg"].svg,
          "max-h-[256px] w-auto",
          className,
          header && "h-12",
        )}
        {...props}
      />
    </div>
  );
}

import { Geist, Geist_Mono, Montserrat } from "next/font/google";
import React, { type ReactNode } from "react";

import { cn } from "@/lib/utils";

import "@/app/tokens.css";
import "@/app/globals.css";

const GeistSans = Geist({
  subsets: ["latin"],
  variable: "--font-sans",
});

const GeistMono = Geist_Mono({
  subsets: ["latin"],
  variable: "--font-mono",
});

const MontserratSerif = Montserrat({
  subsets: ["latin"],
  variable: "--font-serif",
});

export default function RootLayout({
  children,
}: Readonly<{
  children: ReactNode;
}>) {
  return (
    <html
      lang="en"
      className={cn(
        GeistSans.variable,
        GeistMono.variable,
        MontserratSerif.variable,
        "bg-background text-foreground",
      )}
    >
      <body>
        <main className="mt-16 flex w-full justify-center">
          <div className="container">{children}</div>
        </main>
      </body>
    </html>
  );
}

export default function BlankPage() {
  return (
    <div className="flex flex-col items-center justify-center gap-4 rounded-md py-96">
      <div className="text-muted-foreground">
        Start prompting to use your component!
      </div>
    </div>
  );
}
